const key = msg.context.owner + '__' + msg.context.repo;
msg.repoKey = key;
let locks = global.get('arw_repo_locks') || {};
if (locks[key]) {
    setTimeout(function () { node.send(msg); }, 300);
    return null;
}
locks[key] = true;
global.set('arw_repo_locks', locks);
return msg;

const context = msg.context;
const SAFE = /^[A-Za-z0-9._-]+$/;
if (!SAFE.test(context.host) || !SAFE.test(context.owner) || !SAFE.test(context.repo)) {
    // release the lock we just took -- we're bailing before the exec node
    let locks = global.get('arw_repo_locks') || {};
    delete locks[msg.repoKey];
    global.set('arw_repo_locks', locks);
    node.error('arw: refusing unsafe host/owner/repo: ' + context.host + '/' + context.owner + '/' + context.repo, msg);
    msg.payload = {
        timestamp: new Date().toISOString(),
        workflow: context.workflowType,
        type: 'error',
        message: 'refusing unsafe host/owner/repo -- see runtime log'
    };
    return [null, msg];
}
msg.payload = context.host + ' ' + context.owner + ' ' + context.repo;
return [msg, null];

let locks = global.get('arw_repo_locks') || {};
delete locks[msg.repoKey];
global.set('arw_repo_locks', locks);

const rc = msg.rc || { code: 0 };
if (rc.code !== 0) {
    return [null, {
        payload: {
            timestamp: new Date().toISOString(),
            workflow: msg.context.workflowType,
            type: 'error',
            message: 'clone/fetch failed (exit ' + rc.code + '): ' + (rc.message || msg.payload || '')
        }
    }];
}

const text = String(msg.payload || '');
const dirMatch = text.match(/REPO_DIR=(.+)/);
const branchMatch = text.match(/DEFAULT_BRANCH=(.+)/);
msg.cwd = dirMatch ? dirMatch[1].trim() : undefined;
msg.context.defaultBranch = branchMatch ? branchMatch[1].trim() : 'main';

if (!msg.cwd) {
    return [null, {
        payload: {
            timestamp: new Date().toISOString(),
            workflow: msg.context.workflowType,
            type: 'error',
            message: 'clone/fetch script did not report a workspace directory'
        }
    }];
}

return [msg, {
    payload: {
        timestamp: new Date().toISOString(),
        workflow: msg.context.workflowType,
        type: 'info',
        message: 'workspace ready (default branch: ' + msg.context.defaultBranch + ')'
    }
}];

const context = msg.context || {};
const vars = Object.assign({}, context, {
    repoSlug: context.owner + '/' + context.repo
});
msg.payload = String(msg.promptTemplate || '').replace(/\{\{(\w+)\}\}/g, function (match, key) {
    if (Object.prototype.hasOwnProperty.call(vars, key) && vars[key] !== undefined) {
        return vars[key];
    }
    node.warn('arw: unresolved prompt placeholder {{' + key + '}}');
    return match;
});
msg.model = context.model;
return msg;

const context = msg.context;
const exec = msg.agentExecution || {};
const refreshMsg = { context: context };

const logRow = {
    payload: {
        timestamp: new Date().toISOString(),
        workflow: context.workflowType,
        type: exec.status === 'completed' ? 'success' : 'error',
        message: context.workflowType + ' finished: ' + exec.status +
            (exec.durationMs ? ' (' + Math.round(exec.durationMs / 1000) + 's)' : '')
    }
};

return [refreshMsg, logRow];

const set = global.get('arw_running_workflows') || new Set();
set.add(msg._msgid);
global.set('arw_running_workflows', set);
return { payload: set.size + (set.size === 1 ? ' workflow running' : ' workflows running') };

const set = global.get('arw_running_workflows') || new Set();
set.delete(msg._msgid);
global.set('arw_running_workflows', set);
return { payload: set.size + (set.size === 1 ? ' workflow running' : ' workflows running') };

if (!msg.payload || msg.payload.type !== 'error') return null;
const set = global.get('arw_running_workflows') || new Set();
set.delete(msg._msgid);
global.set('arw_running_workflows', set);
return { payload: set.size + (set.size === 1 ? ' workflow running' : ' workflows running') };

msg.payload = {
    timestamp: new Date().toISOString(),
    workflow: (msg.context && msg.context.workflowType) || 'unknown',
    type: 'error',
    message: (msg.error && msg.error.message) ? msg.error.message : 'Unknown agent error'
};
return msg;

const issues = Array.isArray(msg.payload) ? msg.payload : [];
msg.ui_update = {
    options: issues.map(function (issue) {
        return {
            value: issue.number,
            label: '#' + issue.number + ' ' + issue.title
        };
    })
};
return msg;

msg.payload = Object.assign({}, msg.payload, {
    topic: msg.topic,
    executionId: msg.executionId,
    active: msg.active,
    queued: msg.queued,
    timestamp: new Date(msg.timestamp).toISOString()
});
return msg;

msg.payload = Object.assign({}, msg.payload, {
    topic: msg.topic,
    executionId: msg.executionId,
    active: msg.active,
    queued: msg.queued,
    timestamp: new Date(msg.timestamp).toISOString()
});
return msg;

if (flow.get('server_chat_session')) {
    msg.sessionID = flow.get('server_chat_session');
}
return msg;

flow.set('server_chat_session', undefined);
msg.payload = 'New conversation started — the next message spawns a fresh session.';
return msg;

msg.payload = Object.assign({}, msg.payload, {
    sessionID: msg.sessionID,
    active: msg.active,
    tracked: msg.tracked,
    timestamp: new Date(msg.timestamp).toISOString()
});
return msg;

// Most likely cause: the stored sessionID's daemon was already
// killed (e.g. a redeploy) since it was recorded. Clear it so the
// next message starts a fresh session instead of erroring forever.
flow.set('server_chat_session', undefined);
msg.payload = 'Previous session expired -- send your message again to start a new one.';
return msg;

const host = flow.get('icc_host');
const owner = flow.get('icc_owner');
const repo = flow.get('icc_repo');

if (!host || !owner || !repo) {
    return [null, { payload: 'Host, Owner and Repository are all required before updating the issue list.' }];
}

msg.gh = {
    command: 'issue',
    // --state all: otherwise gh only lists open issues, and the open/closed
    // emoji in the radio list would never actually show a closed one.
    args: ['list', '--state', 'all', '--json', 'number,title,state,labels,updatedAt', '--limit', '50'],
    repo: owner + '/' + repo,
    host: host
};
return [msg, null];

const issues = Array.isArray(msg.payload) ? msg.payload : [];
msg.ui_update = {
    options: issues.map(function (issue) {
        const emoji = issue.state === 'CLOSED' ? '🟣' : '🟢';
        return { value: issue.number, label: emoji + ' #' + issue.number + ' ' + issue.title };
    })
};
return msg;

msg.payload = (msg.error && msg.error.message) ? msg.error.message : 'Unknown gh error';

// Only the issue-detail fetch (view/linked-PRs) carries msg.icc -- the
// issue *list* fetch never sets it. Use that to scope the Issue group's
// loading indicator to detail-related errors only.
const loadingMsg = msg.icc ? { payload: "⚠ Update failed: " + msg.payload } : null;

return [msg, loadingMsg];

const issueNumber = Number(msg.payload);
flow.set('icc_selected_issue', issueNumber);
msg.icc = {
    host: flow.get('icc_host'),
    owner: flow.get('icc_owner'),
    repo: flow.get('icc_repo'),
    issueNumber: issueNumber
};
return msg;

const host = flow.get('icc_host');
const owner = flow.get('icc_owner');
const repo = flow.get('icc_repo');
const issueNumber = flow.get('icc_selected_issue');

if (!host || !owner || !repo || issueNumber === undefined) {
    return [null, { payload: 'Select an issue before updating its details.' }];
}

msg.icc = { host, owner, repo, issueNumber };
return [msg, null];

const icc = msg.icc || {};
msg.gh = {
    command: 'issue',
    args: ['view', String(icc.issueNumber), '--json',
           'number,title,state,url,body,comments,labels,assignees,author,updatedAt'],
    repo: icc.owner + '/' + icc.repo,
    host: icc.host
};

const loadingMsg = { payload: '⏳ Updating issue details…' };

return [msg, loadingMsg];

msg.icc.issue = msg.payload;

const query = `query($owner: String!, $repo: String!, $number: Int!) {
  repository(owner: $owner, name: $repo) {
    issue(number: $number) {
      closedByPullRequestsReferences(first: 10, includeClosedPrs: true, userLinkedOnly: false) {
        nodes { number title state url }
      }
    }
  }
}`;

msg.gh = {
    command: 'api',
    args: ['graphql', '-f', 'query=' + query,
           '-F', 'owner=' + msg.icc.owner,
           '-F', 'repo=' + msg.icc.repo,
           '-F', 'number=' + String(msg.icc.issueNumber)],
    repo: '',
    host: msg.icc.host
};
return msg;

const icc = msg.icc || {};
const stillSelected =
    Number(flow.get('icc_selected_issue')) === Number(icc.issueNumber) &&
    flow.get('icc_host') === icc.host &&
    flow.get('icc_owner') === icc.owner &&
    flow.get('icc_repo') === icc.repo;

if (!stillSelected) {
    // The user navigated to a different repo/issue while this fetch was in
    // flight -- drop the render instead of overwriting what they're now
    // looking at (and leave the loading indicator alone: either a newer
    // fetch already owns it, or there isn't one and this is a rare race).
    return [null, null, null, null, null, null];
}

const issue = icc.issue || {};

// --- state badge ---
const STATE_COLORS = { OPEN: '#22c55e', CLOSED: '#8b5cf6' };
const stateColor = STATE_COLORS[issue.state] || '#6b7280';
const stateMsg = { payload:
    "<span style='color:" + stateColor + "; font-weight:600;'>" + (issue.state || 'UNKNOWN') + '</span>' };

// --- linked PRs ---
const prNodes = (msg.payload && msg.payload.data && msg.payload.data.repository &&
    msg.payload.data.repository.issue && msg.payload.data.repository.issue.closedByPullRequestsReferences &&
    msg.payload.data.repository.issue.closedByPullRequestsReferences.nodes) || [];
const PR_COLORS = { OPEN: '#22c55e', MERGED: '#8b5cf6', CLOSED: '#ef4444' };
const prsHtml = prNodes.length
    ? prNodes.map(function (pr) {
        const color = PR_COLORS[pr.state] || '#6b7280';
        return "<a href='" + pr.url + "' target='_blank' style='color:" + color + ";'>#" + pr.number + ' ' + pr.title + '</a>';
    }).join('<br/>')
    : '<em>No linked pull requests</em>';
const linkedPrsMsg = { payload: prsHtml };

const mergeablePr = prNodes.find(function (pr) { return pr.state === 'OPEN'; });
const mergeEligible = issue.state === 'OPEN' && !!mergeablePr;
flow.set('icc_mergeable_pr', mergeEligible ? mergeablePr.number : undefined);
const mergeBtnMsg = { ui_update: { buttonColor: mergeEligible ? '' : '#9ca3af' } };

// --- body (rendered markdown -> sanitized HTML) ---
const bodyMd = issue.body && issue.body.trim() ? issue.body : '_No description provided._';
const bodyMsg = { payload: marked.parse(bodyMd) };

// --- comments (rendered markdown -> sanitized HTML) ---
const comments = Array.isArray(issue.comments) ? issue.comments : [];
const commentsMd = comments.length
    ? comments.map(function (c) {
        const author = (c.author && c.author.login) || 'unknown';
        return '**@' + author + '** commented on ' + c.createdAt + ':\n\n' + c.body;
    }).join('\n\n---\n\n')
    : '_No comments yet._';
const commentsMsg = { payload: marked.parse(commentsMd) };

const clearLoadingMsg = { payload: '' };

return [stateMsg, linkedPrsMsg, bodyMsg, commentsMsg, clearLoadingMsg, mergeBtnMsg];

let rows = flow.get('icc_workflow_log_rows') || [];
rows.unshift(msg.payload);
if (rows.length > 200) rows = rows.slice(0, 200);
flow.set('icc_workflow_log_rows', rows);
msg.payload = rows;
return msg;

const event = msg.payload || {};
const rawMessage = event.type + (event.data !== undefined ? ': ' + JSON.stringify(event.data) : '');
msg.payload = {
    timestamp: new Date(msg.timestamp).toISOString(),
    sessionID: event.sessionID || '',
    message: rawMessage.length > 500 ? rawMessage.slice(0, 500) + '…' : rawMessage
};
return msg;

let rows = flow.get('icc_agent_log_rows') || [];
rows.unshift(msg.payload);
if (rows.length > 300) rows = rows.slice(0, 300);
flow.set('icc_agent_log_rows', rows);
msg.payload = rows;
return msg;

const IMPORTANT = ['queued', 'running', 'completed', 'failed', 'timeout', 'cancelled'];
const type = msg.payload && msg.payload.type;
if (IMPORTANT.indexOf(type) === -1) return null;

msg.payload = {
    timestamp: new Date(msg.timestamp).toISOString(),
    workflow: '[' + msg.executionId + ']',
    type: type,
    message: (msg.payload && msg.payload.data) ? JSON.stringify(msg.payload.data).slice(0, 200) : type
};
return msg;

flow.set('icc_host', '');
flow.set('icc_owner', 'tbrandenburg');
flow.set('icc_repo', 'node-red-agents');
return msg;

msg.payload = {
    workflowLogTimestamps: (flow.get('icc_workflow_log_rows') || []).map(r => r.timestamp + ' ' + r.message),
    agentLogRows: (flow.get('icc_agent_log_rows') || []).map(r => r.timestamp + ' | ' + r.sessionID + ' | ' + r.message)
};
return msg;

const host = flow.get('icc_host');
const owner = flow.get('icc_owner');
const repo = flow.get('icc_repo');

if (!host || !owner || !repo) {
    return [null, { payload: 'Select a repo before running a workflow.' }];
}

msg.context = {
    host, owner, repo,
    model: flow.get('icc_model') || 'github-copilot/claude-sonnet-4.6'
};

return [msg, null];

if (msg.workflowType !== 'investigate') return null;

const issueNumber = flow.get('icc_selected_issue');
if (issueNumber === undefined) {
    return [null, null, { payload: 'Select an issue before running Investigate.' }];
}

msg.context.issueNumber = issueNumber;
msg.context.workflowType = 'investigate';

const logRow = {
    payload: {
        timestamp: new Date().toISOString(),
        workflow: 'investigate',
        type: 'info',
        message: 'investigate requested for #' + issueNumber
    }
};

return [msg, logRow, null];

if (msg.workflowType !== 'fix') return null;

const issueNumber = flow.get('icc_selected_issue');
if (issueNumber === undefined) {
    return [null, null, { payload: 'Select an issue before running Fix.' }];
}

msg.context.issueNumber = issueNumber;
msg.context.workflowType = 'fix';

const logRow = {
    payload: {
        timestamp: new Date().toISOString(),
        workflow: 'fix',
        type: 'info',
        message: 'fix requested for #' + issueNumber
    }
};

return [msg, logRow, null];

msg.payload = 'Could not load the prompt template (' +
    (msg.error && msg.error.message ? msg.error.message : 'unknown error') + ') -- see runtime log.';
return msg;

if (msg.workflowType !== 'merge') return null;

const issueNumber = flow.get('icc_selected_issue');
if (issueNumber === undefined) {
    return [null, null, { payload: 'Select an issue before running Merge Fix.' }];
}

const prNumber = flow.get('icc_mergeable_pr');
if (prNumber === undefined) {
    return [null, null, { payload: 'No open linked pull request to merge for this issue.' }];
}

msg.context.issueNumber = issueNumber;
msg.context.prNumber = prNumber;
msg.context.workflowType = 'merge';

const logRow = {
    payload: {
        timestamp: new Date().toISOString(),
        workflow: 'merge',
        type: 'info',
        message: 'merge requested for PR #' + prNumber + ' (issue #' + issueNumber + ')'
    }
};

return [msg, logRow, null];

// Preserve the original prompt text (agent.js overwrites
// msg.payload with the reply) so the log table can show both
// sides of the turn.
msg.prompt = msg.payload;
if (flow.get('agent_chat_session')) {
    msg.sessionID = flow.get('agent_chat_session');
}
msg.model = flow.get('agent_chat_model') || 'github-copilot/claude-sonnet-4.6';
return msg;

const now = new Date().toISOString();
const reply = msg.payload; // agent's reply text (msg.payload was already
                            // overwritten by agent.js with it)
msg.payload = [
    { sessionID: msg.sessionID, timestamp: now, role: 'User', message: msg.prompt },
    { sessionID: msg.sessionID, timestamp: now, role: 'Agent', message: reply }
];
return msg;

flow.set('agent_chat_session', undefined);
const textMsg = Object.assign({}, msg, { payload: 'New conversation started — the next message starts a fresh session.' });
const clearMsg = Object.assign({}, msg, { payload: [] });
return [textMsg, clearMsg];

// Most likely cause: the model/CLI no longer recognizes the
// stored sessionID (e.g. its data was cleared). Clear it so the
// next message starts a fresh session instead of erroring forever.
flow.set('agent_chat_session', undefined);
msg.payload = 'Previous session expired -- send your message again to start a new one.';
return msg;

const type = msg.payload && msg.payload.type;
const TERMINAL = ['completed', 'failed', 'timeout', 'cancelled'];
const STATES = {
    queued:   { text: '⏳ Queued',    color: '#6b7280' },
    thinking: { text: '🤔 Thinking…', color: '#f59e0b' },
    idle:     { text: '🟢 Idle',      color: '#22c55e' }
};
const key = TERMINAL.includes(type) ? 'idle' : (type === 'queued' ? 'queued' : 'thinking');
const state = STATES[key];
// Colour only the status literal, not the widget's 'Agent Status' label --
// the ui-text widget renders its value via innerHTML, so an inline
// <span style> here is scoped to just this text, unlike msg.ui_update.color
// which would recolor the whole widget (label included).
msg.payload = "<span style='color:" + state.color + "; font-weight:600;'>" + state.text + "</span>";
return msg;

// Clear the backend session so the next message starts fresh.
flow.set('advanced_chat_session', undefined);

// Prime the ui-chat node's persisted state with an empty transcript
// so that when the browser reloads (triggered by the ui-control
// message below), UIChat.vue's onLoad() replaces messages with [].
const clearMsg = { payload: [] };

// Force a page refresh for any client currently viewing this page,
// which re-fires the widget-load event and picks up the empty
// transcript primed above.
const refreshMsg = { payload: { page: '' } };

return [clearMsg, refreshMsg];

// Preserve the original prompt text (agent.js overwrites
// msg.payload with the reply) in case we need it later for
// debugging or logging.
msg.prompt = msg.payload;
if (flow.get('advanced_chat_session')) {
    msg.sessionID = flow.get('advanced_chat_session');
}
msg.model = flow.get('advanced_chat_model') || 'github-copilot/claude-sonnet-4.6';
return msg;

const type = msg.payload && msg.payload.type;
const TERMINAL = ['completed', 'failed', 'timeout', 'cancelled'];
// Only forward a '_typing' hint while the agent is still working;
// the real reply (routed separately via adc-reply-to-chat) clears
// the typing indicator on the client once it arrives.
if (TERMINAL.includes(type)) {
    return null;
}
return { topic: '_typing', payload: true };

// Most likely cause: the model/CLI no longer recognizes the
// stored sessionID (e.g. its data was cleared). Clear it so the
// next message starts a fresh session instead of erroring forever.
flow.set('advanced_chat_session', undefined);
return {
    payload: 'Previous session expired -- send your message again to start a new one.',
    topic: 'System'
};
